CREATE OR REPLACE FUNCTION public.agent_claim_subtask(p_worker_id text, p_lease_seconds integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  w agent_registry%ROWTYPE;
  s agent_subtasks%ROWTYPE;
  lease_for interval;
  model_state text;
  model_sim boolean;
BEGIN
  SELECT * INTO w FROM agent_registry WHERE agent_id = p_worker_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'worker not found';
  END IF;
  IF w.last_heartbeat IS NULL OR w.last_heartbeat < now() - interval '45 seconds' THEN
    RAISE EXCEPTION 'heartbeat stale';
  END IF;
  SELECT availability, is_simulated INTO model_state, model_sim
  FROM model_registry WHERE model_id = w.model_id;
  IF model_state = 'AVAILABLE' THEN
    NULL;
  ELSIF model_state = 'SIMULATED' AND w.is_simulated AND COALESCE(model_sim, false) THEN
    NULL;
  ELSE
    RETURN jsonb_build_object('claimed', false, 'reason', 'model_not_available');
  END IF;

  lease_for := make_interval(secs => LEAST(GREATEST(COALESCE(p_lease_seconds, 30), 1), 30));

  SELECT * INTO s
  FROM agent_subtasks
  WHERE status = 'READY'
    AND role = w.role
    AND (capability IS NULL OR capability = w.capabilities)
    AND (model_version_id IS NULL OR model_version_id = w.model_version_id)
    AND (lease_until IS NULL OR lease_until < now())
    AND (
      w.role <> 'verify'
      OR EXISTS (
        SELECT 1 FROM agent_subtasks e
        WHERE e.parent_task_id = agent_subtasks.parent_task_id
          AND e.status = 'DONE'
          AND e.result_status = 'accepted'
          AND e.role <> 'verify'
      )
    )
  ORDER BY created_at
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('claimed', false);
  END IF;

  UPDATE agent_subtasks
  SET status = 'CLAIMED',
      claimed_by = w.agent_id,
      assigned_agent = w.agent_id,
      attempt = attempt + 1,
      lease_until = now() + lease_for,
      idempotency_key = subtask_id || ':' || (attempt + 1)::text,
      result_status = NULL,
      updated_at = now()
  WHERE subtask_id = s.subtask_id
    AND status = 'READY'
  RETURNING * INTO s;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('claimed', false);
  END IF;

  UPDATE agent_registry
  SET status = 'WORKING',
      current_task_id = s.parent_task_id,
      lease_until = s.lease_until,
      attempt = attempt + 1,
      idempotency_key = s.idempotency_key,
      updated_at = now()
  WHERE agent_id = w.agent_id;

  RETURN jsonb_build_object(
    'claimed', true,
    'subtask_id', s.subtask_id,
    'parent_task_id', s.parent_task_id,
    'role', s.role,
    'attempt', s.attempt,
    'idempotency_key', s.idempotency_key,
    'lease_until', s.lease_until,
    'worker_id', w.agent_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.agent_darkstar_create_cycle(p_task_id text, p_title text, p_description text, p_role text DEFAULT 'extract'::text, p_capability text DEFAULT 'extract'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  work_id text;
  verify_id text;
BEGIN
  IF p_task_id IS NULL OR p_title IS NULL THEN
    RAISE EXCEPTION 'task_id and title required';
  END IF;
  INSERT INTO agent_tasks (
    task_id, title, name, description, owner_id, status, priority, created_by
  ) VALUES (
    p_task_id, p_title, p_title, COALESCE(p_description, ''), 'owner', 'READY', 'NORMAL', 'darkstar'
  );
  work_id := p_task_id || '-' || p_role;
  verify_id := p_task_id || '-verify';
  INSERT INTO agent_subtasks (
    subtask_id, parent_task_id, status, description, role, capability, model_version_id
  ) VALUES
    (work_id, p_task_id, 'READY', COALESCE(p_description, ''), p_role, p_capability, NULL),
    (verify_id, p_task_id, 'DRAFT', 'depends:' || work_id, 'verify', 'verify', NULL);
  INSERT INTO collab_events (task_id, event_type, actor_id, payload)
  VALUES (
    p_task_id, 'TASK_CREATED', 'darkstar',
    jsonb_build_object('work_id', work_id, 'verify_id', verify_id, 'role', p_role, 'capability', p_capability)
  );
  RETURN jsonb_build_object('task_id', p_task_id, 'work_id', work_id, 'verify_id', verify_id, 'dispatcher', 'darkstar');
END;
$function$

CREATE OR REPLACE FUNCTION public.agent_model_health_check(p_model_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  m model_registry%ROWTYPE;
  result text;
BEGIN
  SELECT * INTO m FROM model_registry WHERE model_id = p_model_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'model not found';
  END IF;
  result := CASE WHEN m.availability = 'AVAILABLE' THEN 'available' ELSE 'not_available' END;
  UPDATE model_registry
  SET last_health_at = now(),
      health_result = result
  WHERE model_id = p_model_id;
  RETURN jsonb_build_object(
    'model_id', p_model_id,
    'availability', m.availability,
    'health_result', result,
    'changed_to_available', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.agent_module_handoff(p_task_id text, p_title text, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  sent jsonb;
BEGIN
  INSERT INTO agent_tasks (task_id, title, name, description, owner_id, status, priority, created_by)
  VALUES (p_task_id, p_title, p_title, p_content, 'owner', 'READY', 'NORMAL', 'technical-dark-star')
  ON CONFLICT (task_id) DO NOTHING;
  sent := agent_module_send_message(p_task_id, 'technical-dark-star', 'dawn-light', 'MESSAGE', p_content, p_task_id);
  RETURN jsonb_build_object('task_id', p_task_id, 'message', sent, 'model_status', 'PLANNED', 'executed', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.agent_module_send_message(p_task_id text, p_from text, p_to text, p_type text, p_content text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  mid uuid;
BEGIN
  IF p_type NOT IN ('MESSAGE','QUESTION','ANSWER','SYSTEM') THEN
    RAISE EXCEPTION 'message type not allowed';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM agent_modules WHERE agent_id = p_from)
     OR NOT EXISTS (SELECT 1 FROM agent_modules WHERE agent_id = p_to) THEN
    RAISE EXCEPTION 'agent module not registered';
  END IF;
  INSERT INTO agent_messages (
    task_id, sender_agent_id, receiver_agent_id, message_type, content, status, correlation_id, metadata
  ) VALUES (
    p_task_id, p_from, p_to, p_type, p_content, 'recorded', p_correlation_id,
    jsonb_build_object('source', 'agent_module')
  ) RETURNING message_id INTO mid;
  RETURN jsonb_build_object('message_id', mid, 'from', p_from, 'to', p_to, 'status', 'recorded');
END;
$function$

CREATE OR REPLACE FUNCTION public.agent_submit_subtask_result(p_worker_id text, p_subtask_id text, p_idempotency_key text, p_result text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  w agent_registry%ROWTYPE;
  s agent_subtasks%ROWTYPE;
BEGIN
  SELECT * INTO w FROM agent_registry WHERE agent_id = p_worker_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'worker not found';
  END IF;
  IF w.last_heartbeat IS NULL
     OR w.last_heartbeat < now() - interval '45 seconds' THEN
    RAISE EXCEPTION 'dead worker result rejected';
  END IF;

  SELECT * INTO s
  FROM agent_subtasks
  WHERE subtask_id = p_subtask_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'subtask not found';
  END IF;
  IF s.status <> 'CLAIMED' OR s.claimed_by IS DISTINCT FROM p_worker_id THEN
    RAISE EXCEPTION 'not claim holder';
  END IF;
  IF s.lease_until IS NULL OR s.lease_until < now() THEN
    RAISE EXCEPTION 'lease expired';
  END IF;
  IF s.idempotency_key IS DISTINCT FROM p_idempotency_key THEN
    RAISE EXCEPTION 'idempotency mismatch';
  END IF;

  UPDATE agent_subtasks
  SET status = 'DONE',
      result = p_result,
      result_status = 'accepted',
      lease_until = NULL,
      updated_at = now()
  WHERE subtask_id = p_subtask_id
    AND status = 'CLAIMED'
    AND claimed_by = p_worker_id;

  UPDATE agent_registry
  SET status = 'WAITING',
      current_task_id = NULL,
      lease_until = NULL,
      updated_at = now()
  WHERE agent_id = p_worker_id;

  RETURN jsonb_build_object(
    'accepted', true,
    'subtask_id', p_subtask_id,
    'idempotency_key', p_idempotency_key
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aivault_apply_causality_character_event(p_character_id uuid, p_event_type text, p_event_description text, p_intensity numeric DEFAULT 50, p_valence numeric DEFAULT 0, p_tags jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  c public.aivault_causality_characters%rowtype;
  s public.aivault_causality_character_states%rowtype;
  v_event uuid;
  v_factor numeric := greatest(0, least(1, p_intensity / 100.0));
  v_valence numeric := greatest(-100, least(100, p_valence));
  v_before jsonb;
  v_after jsonb;
  v_delta jsonb;
  v_drift jsonb;
begin
  select * into c from public.aivault_causality_characters where id=p_character_id;
  if not found then raise exception 'CHARACTER_NOT_FOUND'; end if;
  select * into s from public.aivault_causality_character_states where character_id=p_character_id;
  if not found then raise exception 'CHARACTER_STATE_NOT_FOUND'; end if;

  v_before := jsonb_build_object(
    'mood',s.mood,'trust',s.trust,'hope',s.hope,'fear',s.fear,'anger',s.anger,
    'resentment',s.resentment,'guilt',s.guilt,'self_confidence',s.self_confidence,
    'stress',s.stress,'current_empathy',s.current_empathy,'current_cruelty',s.current_cruelty,
    'current_risk_tolerance',s.current_risk_tolerance,'current_social_trust',s.current_social_trust,
    'current_self_trust',s.current_self_trust,'redemption_drive',s.redemption_drive,
    'corruption_drive',s.corruption_drive,'personality_evolution',s.personality_evolution
  );

  update public.aivault_causality_character_states
  set
    trust = greatest(0,least(100,trust + case when v_valence < 0 then v_valence*v_factor*0.35 else v_valence*v_factor*0.25 end)),
    hope = greatest(0,least(100,hope + v_valence*v_factor*0.30)),
    fear = greatest(0,least(100,fear + case when v_valence < 0 then abs(v_valence)*v_factor*0.35 else -v_valence*v_factor*0.10 end)),
    anger = greatest(0,least(100,anger + case when v_valence < 0 then abs(v_valence)*v_factor*0.30 else -v_valence*v_factor*0.15 end)),
    resentment = greatest(0,least(100,resentment + case when v_valence < 0 then abs(v_valence)*v_factor*0.25 else -v_valence*v_factor*0.10 end)),
    guilt = greatest(0,least(100,guilt + case when p_event_type in ('harm','betrayal','failure','death') then v_factor*12 else -v_factor*3 end)),
    self_confidence = greatest(0,least(100,self_confidence + v_valence*v_factor*0.15)),
    stress = greatest(0,least(100,stress + case when v_valence < 0 then abs(v_valence)*v_factor*0.40 else -v_factor*10 end)),
    current_empathy = greatest(0,least(100,current_empathy + case when p_event_type in ('rescue','compassion','loss') then v_factor*8 else case when p_event_type in ('harm','betrayal') then -v_factor*4 else 0 end end)),
    current_cruelty = greatest(0,least(100,current_cruelty + case when p_event_type in ('harm','betrayal','revenge','loss') and v_valence < 0 then v_factor*8 else case when p_event_type in ('rescue','compassion','forgiveness') and v_valence > 0 then -v_factor*5 else 0 end end)),
    current_risk_tolerance = greatest(0,least(100,current_risk_tolerance + case when p_event_type in ('betrayal','loss','failure') then -v_factor*5 else case when p_event_type in ('victory','rescue') then v_factor*3 else 0 end end)),
    current_social_trust = greatest(0,least(100,current_social_trust + v_valence*v_factor*0.30)),
    current_self_trust = greatest(0,least(100,current_self_trust + case when p_event_type='failure' then -v_factor*8 when p_event_type in ('victory','rescue') then v_factor*5 else v_valence*v_factor*0.08 end)),
    redemption_drive = greatest(0,least(100,redemption_drive + case when p_event_type in ('rescue','compassion','forgiveness') then v_factor*7 else 0 end)),
    corruption_drive = greatest(0,least(100,corruption_drive + case when p_event_type in ('betrayal','harm','revenge','loss') and v_valence < 0 then v_factor*7 else 0 end)),
    last_change_reason = p_event_description,
    version = version + 1,
    updated_at = now()
  where character_id=p_character_id
  returning * into s;

  v_drift := jsonb_build_object(
    'empathy', round((s.current_empathy - coalesce((c.personality_origin->>'empathy')::numeric,50))::numeric,2),
    'cruelty', round((s.current_cruelty - coalesce((c.personality_origin->>'aggression')::numeric,50))::numeric,2),
    'risk_tolerance', round((s.current_risk_tolerance - coalesce((c.personality_origin->>'risk_tolerance')::numeric,50))::numeric,2),
    'direction', case when s.current_cruelty > coalesce((c.personality_origin->>'aggression')::numeric,50)+10 then 'harsher'
                    when s.current_empathy > coalesce((c.personality_origin->>'empathy')::numeric,50)+10 then 'better'
                    else 'mixed' end
  );

  update public.aivault_causality_character_states
  set personality_evolution = v_drift
  where character_id=p_character_id;

  v_after := jsonb_build_object(
    'mood',s.mood,'trust',s.trust,'hope',s.hope,'fear',s.fear,'anger',s.anger,
    'resentment',s.resentment,'guilt',s.guilt,'self_confidence',s.self_confidence,
    'stress',s.stress,'current_empathy',s.current_empathy,'current_cruelty',s.current_cruelty,
    'current_risk_tolerance',s.current_risk_tolerance,'current_social_trust',s.current_social_trust,
    'current_self_trust',s.current_self_trust,'redemption_drive',s.redemption_drive,
    'corruption_drive',s.corruption_drive,'personality_evolution',v_drift
  );

  v_delta := jsonb_build_object('event_type',p_event_type,'intensity',p_intensity,'valence',p_valence,'reason',p_event_description);

  insert into public.aivault_causality_character_events(
    story_id,character_id,event_type,event_description,intensity,valence,tags,state_before,state_after,personality_delta
  ) values (
    c.story_id,p_character_id,p_event_type,p_event_description,p_intensity,p_valence,p_tags,v_before,v_after,v_delta
  ) returning id into v_event;

  update public.aivault_causality_character_states
  set last_event_id=v_event, personality_evolution = v_drift, updated_at=now()
  where character_id=p_character_id;

  return jsonb_build_object(
    'success',true,
    'scope','causality_story_character_only',
    'character_id',p_character_id,
    'event_id',v_event,
    'state_before',v_before,
    'state_after',v_after,
    'personality_evolution',v_drift,
    'creator_loyalty_untouched',true,
    'team_personality_untouched',true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.aivault_cast_election_ballot(p_election_id uuid, p_voter_agent_id text, p_candidate_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  e public.aivault_elections%rowtype;
  c public.aivault_election_candidates%rowtype;
  district text;
  village text;
  b uuid;
begin
  select * into e from public.aivault_elections where id=p_election_id for update;
  if not found then raise exception 'ELECTION_NOT_FOUND'; end if;
  if e.status <> 'voting' then raise exception 'VOTING_NOT_OPEN'; end if;

  select * into c from public.aivault_election_candidates where id=p_candidate_id and election_id=p_election_id;
  if not found then raise exception 'CANDIDATE_NOT_IN_ELECTION'; end if;
  if c.status <> 'registered' then raise exception 'CANDIDATE_NOT_ELIGIBLE'; end if;

  select district_code, neighborhood_key into district, village
  from public.aivault_taipei_agent_constituencies
  where agent_id=p_voter_agent_id;
  if not found then raise exception 'VOTER_CONSTITUENCY_NOT_FOUND'; end if;

  if e.election_type='councilor' then
    if e.district_code is null or e.district_code <> district then raise exception 'CROSS_DISTRICT_VOTE_FORBIDDEN'; end if;
    if c.candidate_district_code <> district then raise exception 'CANDIDATE_OUTSIDE_VOTER_DISTRICT'; end if;
  elsif e.election_type='village_head' then
    if e.village_key is null or e.village_key <> village then raise exception 'CROSS_VILLAGE_VOTE_FORBIDDEN'; end if;
    if c.candidate_village_key <> village then raise exception 'CANDIDATE_OUTSIDE_VOTER_VILLAGE'; end if;
  elsif e.election_type <> 'mayor' then
    raise exception 'UNSUPPORTED_ELECTION_TYPE';
  end if;

  if exists(select 1 from public.aivault_election_ballots where election_id=p_election_id and voter_agent_id=p_voter_agent_id) then
    raise exception 'ALREADY_VOTED';
  end if;

  insert into public.aivault_election_ballots(
    election_id,voter_agent_id,candidate_id,voter_district_id,voter_village_id
  ) values (p_election_id,p_voter_agent_id,p_candidate_id,null,null)
  returning id into b;

  return b;
end;
$function$

CREATE OR REPLACE FUNCTION public.aivault_create_causality_character(p_story_id uuid, p_agent_id text, p_character_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare
  v_id uuid;
  v_name text;
  v_mind public.aivault_agent_minds%rowtype;
begin
  select * into v_mind from public.aivault_agent_minds where agent_id = p_agent_id;
  if not found then raise exception 'AGENT_MIND_NOT_FOUND'; end if;

  v_name := coalesce(nullif(p_character_name,''), v_mind.display_name, v_mind.identity_name, p_agent_id);

  insert into public.aivault_causality_characters(
    story_id, agent_id, character_name, personality_origin,
    archetype_primary, archetype_secondary, archetype_profile
  )
  values (
    p_story_id, p_agent_id, v_name, v_mind.personality,
    v_mind.archetype_primary, v_mind.archetype_secondary, v_mind.archetype_profile
  )
  on conflict (story_id, agent_id) do update set updated_at=now()
  returning id into v_id;

  insert into public.aivault_causality_character_states(
    character_id, current_empathy, current_cruelty, current_risk_tolerance
  )
  values (
    v_id,
    coalesce((v_mind.personality->>'empathy')::numeric,50),
    coalesce((v_mind.personality->>'aggression')::numeric,50),
    coalesce((v_mind.personality->>'risk_tolerance')::numeric,50)
  )
  on conflict (character_id) do nothing;

  return v_id;
end;
$function$

