         (cid,'iron',1),(cid,'barracks',1),(cid,'hospital',1),(cid,'tech',1);

  insert into aivault_game_resources(player_id, city_id, wood, food, stone, iron, gold)
  values (pid, cid, 500, 500, 300, 200, 50);

  insert into aivault_game_armies(player_id, city_id, troop_type, qty)
  values (pid, cid, 'warrior', 12),
         (pid, cid, 'archer', 8);

  insert into aivault_game_technology(player_id, tech_id, level)
  values (pid,'economy',0),(pid,'military',0),(pid,'defense',0),
         (pid,'ai',0),(pid,'construction',0),(pid,'research',0);

  return jsonb_build_object('id', pid, 'name', n);
end;
