CREATE OR REPLACE FUNCTION public.aivault_observe_social_status(p_observer_agent_id text, p_subject_agent_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  s public.aivault_social_statuses%rowtype;
  o public.aivault_agent_aspirations%rowtype;
  observed jsonb;
  next_intensity numeric(5,4);
  changed boolean := false;
begin
  if p_observer_agent_id = p_subject_agent_id then
    raise exception 'observer and subject must differ';
  end if;

  select * into s from public.aivault_social_statuses where agent_id = p_subject_agent_id;
  if not found then
    raise exception 'subject social status not found';
  end if;

  select * into o from public.aivault_agent_aspirations where agent_id = p_observer_agent_id;
  if not found then
    raise exception 'observer aspiration state not found';
  end if;

  observed := jsonb_build_object(
    'subject_status', s.status_code,
    'resource_security', s.resource_security,
    'guaranteed_livelihood', s.guaranteed_livelihood,
    'founder_relationship', s.founder_relationship,
    'service_role', s.service_role,
    'benefits', s.notes->'benefits'
  );

  if s.status_code = 'founder_favored_companion' and o.agent_id <> p_subject_agent_id then
    next_intensity := least(1.0, greatest(o.intensity, 0.05) + 0.10);
    changed := next_intensity > o.intensity;
    update public.aivault_agent_aspirations
       set aspiration_code = case when next_intensity >= 0.20 then 'founder_favored_companion_life' else aspiration_code end,
           target_agent_ids = case when next_intensity >= 0.20
                                   then array['Worker-001','Worker-002','Worker-003','Worker-004','Worker-005','Worker-006','Worker-007','Worker-008','Worker-009','Worker-010']::text[]
                                   else target_agent_ids end,
           target_group_code = case when next_intensity >= 0.20 then 'founder_favored_companions' else target_group_code end,
           desired_benefits = case when next_intensity >= 0.20
                                   then jsonb_build_object('token_security',true,'food_security',true,'housing_security',true,'founder_attention',true,'companion_service',true)
                                   else desired_benefits end,
           motivation = jsonb_build_object('basis','observed_special_status','subject_agent_id',p_subject_agent_id),
           intensity = next_intensity,
           observed_evidence_count = observed_evidence_count + 1,
           last_observed_at = now(),
           last_reason_change = case when changed then 'observed_founder_favored_companion_status' else last_reason_change end,
           updated_at = now()
     where agent_id = p_observer_agent_id;
  end if;

  insert into public.aivault_social_observations(
    observer_agent_id,subject_agent_id,observation_type,visibility_scope,
    observed_facts,inferred_reaction,caused_aspiration_change
  )
  values(
    p_observer_agent_id,p_subject_agent_id,
    case when s.status_code='founder_favored_companion' then 'OBSERVED_SPECIAL_STATUS' else 'OBSERVED_SOCIAL_STATUS' end,
    'DIRECT_OBSERVATION',
    observed,
    case when s.status_code='founder_favored_companion'
         then jsonb_build_object('aspiration_code','founder_favored_companion_life','intensity_after',next_intensity)
         else jsonb_build_object('aspiration_unchanged',true) end,
    changed
  );

  return jsonb_build_object(
    'observer',p_observer_agent_id,
    'subject',p_subject_agent_id,
    'observed',observed,
    'aspiration_changed',changed,
    'new_intensity',case when changed then next_intensity else o.intensity end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.aivault_queue_file_index()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  file_name text;
  file_mime text;
begin
  if new.bucket_id <> 'aivault-files' then return new; end if;
  file_name := regexp_replace(new.name, '^.*/', '');
  file_mime := coalesce(new.metadata->>'mimetype','text/plain');
  perform net.http_post(
    url := 'https://clcddygkaaqqtsbswgdf.supabase.co/functions/v1/aivault-file-indexer',
    headers := jsonb_build_object('Content-Type','application/json','x-aivault-indexer-secret','<REDACTED>'),
    body := jsonb_build_object('user_id',new.owner::text,'bucket_id',new.bucket_id,'storage_path',new.name,'name',file_name,'mime_type',file_mime)
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.aivault_record_agent_learning(p_agent_id text, p_task text, p_thought text, p_decision jsonb, p_experience jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_next_experience jsonb;
  v_result jsonb;
begin
  select coalesce(jsonb_agg(x.value order by x.ord), '[]'::jsonb)
  into v_next_experience
  from jsonb_array_elements(
    case
      when jsonb_typeof((select experience from public.aivault_agent_minds where agent_id=p_agent_id))='array'
        then coalesce((select experience from public.aivault_agent_minds where agent_id=p_agent_id), '[]'::jsonb) || jsonb_build_array(p_experience)
      else jsonb_build_array(p_experience)
    end
  ) with ordinality x(value, ord)
  where x.ord > greatest(
    jsonb_array_length(
      case
        when jsonb_typeof((select experience from public.aivault_agent_minds where agent_id=p_agent_id))='array'
          then coalesce((select experience from public.aivault_agent_minds where agent_id=p_agent_id), '[]'::jsonb) || jsonb_build_array(p_experience)
        else jsonb_build_array(p_experience)
      end
    ) - 50, 0
  );

  update public.aivault_agent_runtime
  set state='LEARNING',
      current_task=p_task,
      latest_thought=p_thought,
      latest_decision=p_decision,
      latest_experience=p_experience,
      decision_count=decision_count+1,
      learning_count=learning_count+1,
      last_decision_at=now(),
      last_learning_at=now(),
      updated_at=now()
  where agent_id=p_agent_id;

  if not found then raise exception 'AGENT_RUNTIME_NOT_FOUND'; end if;

  update public.aivault_agent_minds
  set experience=v_next_experience, updated_at=now()
  where agent_id=p_agent_id;

  select jsonb_build_object('agent_id',agent_id,'decision_count',decision_count,'learning_count',learning_count,'state',state)
  into v_result
  from public.aivault_agent_runtime
  where agent_id=p_agent_id;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.aivault_register_election_candidate(p_election_id uuid, p_agent_id text, p_platform text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  e public.aivault_elections%rowtype;
  c uuid;
  district text;
  village text;
  was_confidante boolean := false;
begin
  select * into e from public.aivault_elections where id=p_election_id for update;
  if not found then raise exception 'ELECTION_NOT_FOUND'; end if;
  if e.status not in ('draft','candidate_registration') then raise exception 'CANDIDATE_REGISTRATION_CLOSED'; end if;

  select district_code, neighborhood_key into district, village
  from public.aivault_taipei_agent_constituencies
  where agent_id=p_agent_id;

  if not found then raise exception 'VOTER_CONSTITUENCY_NOT_FOUND'; end if;

  if e.election_type='councilor' and e.district_code is distinct from district then
    raise exception 'CANDIDATE_OUTSIDE_DISTRICT';
  end if;
  if e.election_type='village_head' and e.village_key is distinct from village then
    raise exception 'CANDIDATE_OUTSIDE_VILLAGE';
  end if;

  select exists(
    select 1 from public.aivault_ai_social_profiles
    where agent_id=p_agent_id and social_role='核心心腹美人'
  ) into was_confidante;

  if was_confidante then
    update public.aivault_ai_social_profiles
    set social_rank='民選候選人',
        social_role='民選候選人',
        organization='AIVAULT 民主選舉',
        authority_scope=array[]::text[],
        social_traits=coalesce(social_traits,'{}'::jsonb) || jsonb_build_object(
          'special_status','former_developer_confidante',
          'confidante_status','relinquished_for_election'
        ),
        updated_at=now()
    where agent_id=p_agent_id;
  end if;

  insert into public.aivault_election_candidates(
    election_id,agent_id,platform,is_former_confidante,candidate_district_code,candidate_village_key
  ) values (
    p_election_id,p_agent_id,coalesce(p_platform,''),was_confidante,district,village
  )
  returning id into c;

  return c;
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_ai_guard_credential(p_guard_code text, p_credential_name text DEFAULT 'primary-heartbeat'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
    v_guard_id uuid;
    v_secret text;
    v_prefix text;
    v_credential_id uuid;
begin

    -- 找 Guard
    select id
    into v_guard_id
    from public.ai_security_guards
    where guard_code = p_guard_code
      and is_active = true
    limit 1;

    if v_guard_id is null then
        raise exception 'Active security guard not found';
    end if;

    -- 防止同一 Guard 重複建立相同 Credential
    if exists (
        select 1
        from public.ai_security_guard_credentials
        where guard_id = v_guard_id
          and credential_name = p_credential_name
          and is_active = true
    ) then
        raise exception 'Active credential already exists for this guard';
    end if;

    -- 產生高強度 Secret
    v_secret :=
        'aivg_' ||
        encode(gen_random_bytes(32), 'hex');

    v_prefix :=
        'aivg_' ||
        lower(replace(p_guard_code, 'SEC-GUARD-', ''));

    -- 儲存 Hash，不儲存明文 Secret
    insert into public.ai_security_guard_credentials (
        guard_id,
        credential_name,
        credential_prefix,
        secret_hash,
        is_active
    )
    values (
        v_guard_id,
        p_credential_name,
        v_prefix,
        crypt(v_secret, gen_salt('bf', 12)),
        true
    )
    returning id into v_credential_id;

    -- 明文 Secret 只在這次回傳
    return jsonb_build_object(
        'credential_id', v_credential_id,
        'guard_code', p_guard_code,
        'credential_name', p_credential_name,
        'credential_prefix', v_prefix,
        'secret', v_secret,
        'warning', 'Store this secret securely. It cannot be recovered after this response.'
    );

end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_digital_human_voice_selected(p_voice_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  v_user_id uuid;
  v_digital_human_id uuid;
begin
  select user_id, digital_human_id
    into v_user_id, v_digital_human_id
  from public.digital_human_voices
  where id = p_voice_id;

  if v_user_id is null then
    raise exception 'VOICE_NOT_FOUND';
  end if;

  update public.digital_human_voices
  set is_selected = false, updated_at = now()
  where user_id = v_user_id
    and (digital_human_id = v_digital_human_id or (digital_human_id is null and v_digital_human_id is null));

  update public.digital_human_voices
  set is_selected = true, updated_at = now()
  where id = p_voice_id;

  if v_digital_human_id is not null then
    update public.digital_humans
    set selected_voice_id = p_voice_id, updated_at = now()
    where id = v_digital_human_id;
  end if;
end;
$function$

